"""Procedural Treenoc rig parts + rig.json. Original art generated by this script (no legacy pixels used).
Run: python3 tools/assets/rig-gen/treenoc.py <out_rig_dir>  (needs Pillow + numpy; no copied pixels)
"""
import json, os, sys, zlib
import numpy as np
from PIL import Image, ImageDraw, ImageFilter

OUT = sys.argv[1]
os.makedirs(os.path.join(OUT, "parts"), exist_ok=True)
SS = 4  # supersample

# palette sampled by eye from the legacy sprite: tan-brown bark, darker roots, pale twigs, a little moss
BARK = (118, 102, 72)
BARK_D = (74, 62, 44)
ROOT = (96, 84, 58)
ROOT_D = (66, 58, 40)
TWIG = (168, 148, 102)
TWIG_D = (118, 100, 66)
MOSS = (104, 112, 64)
EYE = (24, 20, 14)
GLOW = (214, 226, 120)
TAN = TWIG

# ---- geometry in the 80x80 rest frame, E view (point lists, y down) ----
G = {
 "hips": dict(pts=[(12,64),(20,52),(34,48),(48,50),(58,58),(64,68),(54,72),(36,70),(20,72)], joint=(36,58), col=ROOT, z=3, parent=None),
 "legB": dict(pts=[(18,62),(30,60),(34,68),(36,76),(30,79),(24,74),(18,78),(10,79),(12,72),(16,68)], joint=(26,62), col=ROOT_D, z=1, parent="hips"),
 "legF": dict(pts=[(38,62),(52,60),(58,66),(66,72),(72,79),(62,77),(54,79),(44,79),(46,72),(40,68)], joint=(48,62), col=ROOT, z=4, parent="hips"),
 "armB": dict(pts=[(40,28),(50,28),(58,34),(66,40),(74,42),(76,48),(66,48),(58,46),(50,42),(42,38)], joint=(44,30), col=BARK_D, z=2, parent="torso", spikes=[(72,42,1),(76,46,1),(70,48,1)]),
 "crown": dict(pts=[], joint=(34,24), col=TWIG_D, z=5, parent="torso"),
 "torso": dict(pts=[(16,62),(18,48),(16,36),(20,26),(28,20),(38,18),(46,22),(50,32),(52,44),(54,54),(52,62),(40,66),(28,66)], joint=(34,44), col=BARK, z=6, parent="hips"),
 "head": dict(pts=[(40,20),(46,14),(54,13),(60,17),(62,24),(58,31),(50,34),(43,30)], joint=(46,26), col=BARK, z=7, parent="torso"),
 "armF": dict(pts=[(14,28),(24,26),(28,36),(26,48),(22,58),(24,66),(16,72),(8,70),(10,62),(8,52),(10,40)], joint=(19,30), col=BARK, z=8, parent="torso", spikes=[(10,70,2),(18,74,2),(26,68,2),(7,60,2)]),
}
SPIKE_BASE = [(18,30),(23,24),(29,20),(35,18),(41,19),(46,22),(50,28)]

# ---- per-view transforms: x scale about cx, shifts, per part ----
def view_tf(view, part):
    if view == "E":
        return dict(sx=1.0, dx=-4 if part == "head" else 0, dy=0)
    if view == "SE":  # three-quarter toward the camera: narrower, head lower and bigger, arms apart
        d = dict(sx=0.92, dx=2, dy=1)
        if part == "head": d = dict(sx=1.08, dx=-10, dy=4, scale=1.08)
        if part == "armF": d = dict(sx=0.95, dx=-3, dy=1)
        if part == "armB": d = dict(sx=0.95, dx=3, dy=1)
        if part == "torso": d = dict(sx=0.96, dx=1, dy=2)
        return d
    if view == "NE":  # seen from behind: head smaller and higher, spikes tall
        d = dict(sx=0.92, dx=-1, dy=-1)
        if part == "head": d = dict(sx=0.9, dx=-7, dy=-2, scale=0.92)
        if part == "armF": d = dict(sx=0.95, dx=1, dy=-1)
        if part == "armB": d = dict(sx=0.95, dx=2, dy=-1)
        if part == "torso": d = dict(sx=1.0, dx=-2, dy=-1)
        return d

def apply(tf, p, c=(40, 40)):
    s = tf.get("scale", 1.0)
    x = c[0] + (p[0] - c[0]) * tf["sx"] * s + tf["dx"]
    y = c[1] + (p[1] - c[1]) * s + tf["dy"]
    return (x, y)

def noise(shape, rs, scale):
    h, w = shape
    small = rs.rand(h // scale + 2, w // scale + 2)
    im = Image.fromarray((small * 255).astype(np.uint8)).resize((w, h), Image.BICUBIC)
    return np.asarray(im, dtype=np.float32) / 255.0

def render(name, view, pts, spikes_extra, col, dark_edge, seed):
    """Return (RGBA image cropped to bbox, (x0, y0) of crop in frame coords)."""
    W = 80 * SS
    m = Image.new("L", (W, W), 0)
    d = ImageDraw.Draw(m)
    sp = []
    tipcol = TWIG
    if name == "crown":
        # a row of tall tan spikes along the back, base hidden under the torso
        for i, (bx, by) in enumerate(pts):
            h = 17 + (i * 7) % 7 + (3 if view == "NE" else 0)
            lean = (i - 3) * 3.4  # branches fan out like antlers
            tx, ty = bx + lean, by - h
            sp.append(((bx - 3, by + 6), (bx + 3, by + 6), (tx, ty)))
            mx, my = bx + lean * 0.5, by - h * 0.55  # a side twig on every branch
            dirn = -1 if i % 2 else 1
            sp.append(((mx - 1, my + 1.5), (mx + 1, my + 2.5), (mx + dirn * 7, my - 6)))
    for (bx, by, r) in spikes_extra or []:
        pass
    if pts and name != "crown":
        d.polygon([(x * SS, y * SS) for x, y in pts], fill=255)
    for tri in sp:
        d.polygon([(x * SS, y * SS) for x, y in tri], fill=255)
    for (x, y, r) in spikes_extra or []:
        # small knuckle spikes poking out of the arm (kept in the mask, tan-coloured below)
        d.polygon([((x - 3) * SS, (y + 1) * SS), ((x + 3) * SS, (y - 1) * SS), ((x + 1 + 2 * r) * SS, (y - 4 - r) * SS)], fill=255)
    m = m.filter(ImageFilter.GaussianBlur(SS * 0.35))
    ma = np.asarray(m, dtype=np.float32) / 255.0
    rs = np.random.RandomState(seed)
    n1 = noise((W, W), rs, SS * 5)
    n2 = noise((W, W), rs, SS * 2)
    yy, xx = np.mgrid[0:W, 0:W].astype(np.float32) / W
    light = 1.12 - 0.5 * yy - 0.25 * xx + 0.0  # lit from the upper left
    tone = np.clip(light * (0.82 + 0.3 * n1 + 0.14 * n2), 0.4, 1.35)
    base = np.array(col, dtype=np.float32)
    rgb = base[None, None, :] * tone[..., None]
    if name == "crown":
        rgb = np.array(TWIG_D, dtype=np.float32)[None, None, :] * tone[..., None]
    # darker rim: erode the mask and darken the outer band
    inner = np.asarray(m.filter(ImageFilter.MinFilter(SS * 2 + 1)), dtype=np.float32) / 255.0
    rim = np.clip(np.subtract(ma, inner), 0, 1)  # np.subtract: the operator form mutated ma on one numpy build
    rgb = rgb * (1 - 0.3 * rim[..., None])
    # plate cracks: a few dark ridges from noise thresholding (bark parts only)
    if name in ("torso", "armF", "armB", "head", "hips", "legF", "legB"):
        ridge = np.abs(n2 - 0.5) < 0.035
        rgb = np.where(ridge[..., None], rgb * 0.7, rgb)
    if name == "head":
        pass
    # tan pointed spikes on arms: tint pixels outside the base polygon
    if spikes_extra:
        pm = Image.new("L", (W, W), 0)
        ImageDraw.Draw(pm).polygon([(x * SS, y * SS) for x, y in pts], fill=255)
        pa = np.asarray(pm, dtype=np.float32) / 255.0
        out = (ma > 0.5) & (pa < 0.5)
        rgb = np.where(out[..., None], np.array(TWIG, dtype=np.float32)[None, None, :] * tone[..., None], rgb)
    img = np.dstack([np.clip(rgb, 0, 255), ma * 255.0]).astype(np.uint8)
    im = Image.fromarray(img, "RGBA")
    return im

def eye(im, p, view):
    d = ImageDraw.Draw(im)
    x, y = p[0] * SS, p[1] * SS
    d.ellipse([x - 2.6 * SS, y - 2.0 * SS, x + 2.6 * SS, y + 2.0 * SS], fill=EYE + (255,))
    d.ellipse([x - 1.2 * SS, y - 0.9 * SS, x + 1.2 * SS, y + 0.9 * SS], fill=GLOW + (255,))

def hollow(im, box):
    """A dark knot-hole in the trunk (box in frame coords)."""
    d = ImageDraw.Draw(im)
    d.ellipse([c * SS for c in box], fill=EYE + (230,))

def belly(im, pts, alpha):
    pass

parts = []
for view in ("E", "SE", "NE"):
    tfs = {k: view_tf(view, k) for k in G}
    for k, g in G.items():
        tf = tfs[k]
        if k == "crown":
            pts = [apply(tfs["torso"], p) for p in SPIKE_BASE]
            spk = None
        else:
            pts = [apply(tf, p) for p in g["pts"]]
            spk = [(*apply(tf, (s[0], s[1])), s[2]) for s in g.get("spikes", [])]
        im = render(k, view, pts, spk, g["col"], None, zlib.crc32((k+view).encode()) % 9973 + 7)
        if k == "head":
            if view != "NE":
                e = apply(tf, (53, 21))
                eye(im, e, view)
                m0 = apply(tf, (56, 28))
                ImageDraw.Draw(im).line([(m0[0] * SS, m0[1] * SS), ((m0[0] + 4) * SS, (m0[1] + 1) * SS)], fill=EYE + (255,), width=SS)
        if k == "torso":
            hx0, hy0 = apply(tf, (28, 36))
            hollow(im, (hx0, hy0, hx0 + 8, hy0 + 14))
        if k == "torso" and view == "SE":
            # mossy patch toward the viewer
            d = ImageDraw.Draw(im, "RGBA")
            bx = [apply(tf, p) for p in [(26, 34), (44, 32), (52, 44), (40, 54), (24, 50)]]
            ov = Image.new("RGBA", im.size, (0, 0, 0, 0))
            ImageDraw.Draw(ov).ellipse([37 * SS, 44 * SS, 52 * SS, 62 * SS], fill=MOSS + (140,))
            ov = ov.filter(ImageFilter.GaussianBlur(SS * 2))
            a0 = np.asarray(im)[..., 3]
            ova = np.asarray(ov).copy(); ova[..., 3] = (ova[..., 3].astype(np.float32) * a0 / 255.0).astype(np.uint8)
            im = Image.alpha_composite(im, Image.fromarray(ova, "RGBA"))
        # downscale
        small = im.resize((80, 80), Image.LANCZOS)
        a = np.asarray(small)
        ys, xs = np.nonzero(a[..., 3] > 8)
        x0, x1, y0, y1 = int(xs.min()), int(xs.max()) + 1, int(ys.min()), int(ys.max()) + 1
        crop = small.crop((x0, y0, x1, y1))
        fname = f"{k}.png" if view == "E" else f"{k}_{view.lower()}.png"
        crop.save(os.path.join(OUT, "parts", fname))
        j = apply(tf, g["joint"]) if k != "crown" else apply(tfs["torso"], g["joint"])
        parts.append(dict(view=view, id=k, png=fname, joint=j, off=(x0, y0), size=crop.size))

# ---- assemble rig.json ----
def pv(e, view):
    j = e["joint"]
    return [int(round(j[0])) - e["off"][0], int(round(j[1])) - e["off"][1]]

byv = {v: {e["id"]: e for e in parts if e["view"] == v} for v in ("E", "SE", "NE")}
def at(v, pid):
    g = G[pid]
    e = byv[v][pid]
    jx, jy = int(round(e["joint"][0])), int(round(e["joint"][1]))
    if g["parent"] is None:
        return [jx, jy]
    pe = byv[v][g["parent"]]
    return [jx - int(round(pe["joint"][0])), jy - int(round(pe["joint"][1]))]

order = ["head", "armF", "torso", "crown", "legF", "hips", "armB", "legB"]
rig_parts = []
for pid in order:
    g = G[pid]
    p = {"id": pid}
    if g["parent"]: p["parent"] = g["parent"]
    p["png"] = byv["E"][pid]["png"]
    p["pivot"] = pv(byv["E"][pid], "E")
    p["at"] = at("E", pid)
    p["z"] = g["z"]
    views = {}
    for v in ("SE", "NE"):
        views[v] = {"png": byv[v][pid]["png"], "pivot": pv(byv[v][pid], v), "at": at(v, pid)}
    p["views"] = views
    rig_parts.append(p)

def c(**kw): return kw
actions = {
 "idle": dict(frames=4, curves={
    "torso": c(rot=[0, 0, 1, 1], dy=[0, 0, 1, 1]),
    "head": c(rot=[0, -1, -1, 0]),
    "armF": c(rot=[0, 1, 2, 1]),
    "armB": c(rot=[0, -1, -2, -1]),
    "crown": c(rot=[0, 1, 1, 0]),
 }),
 "walk": dict(frames=4, curves={
    "hips": c(rot=[2, 2, 2, 2], dy=[1, 0, -1, 0]),
    "torso": c(rot=[2, 2, 2, 2], dy=[0, 1, 0, 1]),
    "head": c(rot=[-2, -1, -2, -1], dy=[0, 0, 1, 0]),
    "legF": c(rot=[-12, 0, 12, 0], dy=[0, -1, 0, 0]),
    "legB": c(rot=[12, 0, -12, 0], dy=[0, 0, 0, -1]),
    "armF": c(rot=[5, 0, -9, 0]),
    "armB": c(rot=[-9, 0, 5, 0]),
 }),
 # earth buff: both arms heave up and forward, torso rears back, then slams
 "cast": dict(frames=4, curves={
    "torso": c(rot=[0, -4, -3, 2], dy=[0, 1, 0, 2]),
    "head": c(rot=[-2, -6, -4, 3], dx=[0, -1, 0, 1]),
    "armF": c(rot=[-8, -30, -48, -18]),
    "armB": c(rot=[-6, -26, -40, -14]),
    "crown": c(rot=[0, -2, -1, 1]),
    "legF": c(dy=[0, 0, 0, 1]),
    "legB": c(dy=[0, 0, 0, 1]),
 }),
}
json.dump(dict(dirs=["E", "SE", "NE"], parts=rig_parts, actions=actions), open(os.path.join(OUT, "rig.json"), "w"), indent=2)
open(os.path.join(OUT, "license.txt"), "w").write(
"""Rig parts for treenoc: original art generated by tools/assets/rig-gen/treenoc.py (WP-rig-treenoc, 2026-11-11, Claude). No pixels
are copied; colours and silhouette chosen by eye after the legacy public/assets/img/map/treenoc.png. Licence: same as the
repository's own original code and art (still to be decided in README.md; owner to confirm).
""")
print("ok")
